program='''def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    if all(v == 2 for v in g[0]):
        dr = 1
    elif all(v == 2 for v in g[-1]):
        dr = -1
    else:
        raise ValueError("expected a full 2-colored horizontal boundary")

    seen = set()
    pieces = []
    for r in range(h):
        for c in range(w):
            if g[r][c] == 0 or g[r][c] == 2 or (r, c) in seen:
                continue
            color = g[r][c]
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and g[yy][xx] == color:
                        seen.add((yy,xx))
                        stack.append((yy,xx))
            pieces.append((color, cells))

    # Move each connected piece one cell at a time toward the 2 boundary.
    while True:
        occupied = {(r,c) for _, cells in pieces for r,c in cells}
        moving = []
        for i, (color, cells) in enumerate(pieces):
            dest = [(r+dr,c) for r,c in cells]
            if all(0 <= r < h and 0 <= c < w and g[r][c] != 2 and ((r,c) not in occupied or (r,c) in cells) for r,c in dest):
                moving.append(i)
        if not moving:
            break
        for i in moving:
            color, cells = pieces[i]
            pieces[i] = (color, [(r+dr,c) for r,c in cells])

    out = [[0]*w for _ in range(h)]
    for r,c in [(r,c) for r in range(h) for c in range(w) if g[r][c] == 2]:
        out[r][c] = 2
    for color,cells in pieces:
        for r,c in cells:
            out[r][c] = color
    return out
'''
